import sys

def make_tree(depth):
    if depth == 0:
        return (None, None)
    return (make_tree(depth - 1), make_tree(depth - 1))

def check_tree(node):
    l, r = node
    if l is None:
        return 1
    return 1 + check_tree(l) + check_tree(r)

def main():
    n = int(sys.argv[1])
    min_depth = 4
    max_depth = max(min_depth + 2, n)
    stretch_depth = max_depth + 1

    stretch = make_tree(stretch_depth)
    print("stretch tree of depth {0}\t check: {1}".format(stretch_depth, check_tree(stretch)))
    del stretch

    long_lived = make_tree(max_depth)

    for depth in range(min_depth, max_depth + 1, 2):
        iterations = 1 << (max_depth - depth + min_depth)
        chk = 0
        for _ in range(iterations):
            chk += check_tree(make_tree(depth))
        print("{0}\t trees of depth {1}\t check: {2}".format(iterations, depth, chk))

    print("long lived tree of depth {0}\t check: {1}".format(max_depth, check_tree(long_lived)))

if __name__ == "__main__":
    main()
```

