import sys
from math import sqrt

def A(i, j):
    return 1.0 / ((i + j) * (i + j + 1) // 2 + i + 1)

def mult_Av(v, out, n):
    for i in range(n):
        s = 0.0
        for j in range(n):
            s += A(i, j) * v[j]
        out[i] = s

def mult_Atv(v, out, n):
    for i in range(n):
        s = 0.0
        for j in range(n):
            s += A(j, i) * v[j]
        out[i] = s

def mult_AtAv(v, out, tmp, n):
    mult_Av(v, tmp, n)
    mult_Atv(tmp, out, n)

def main():
    n = int(sys.argv[1])
    u = [1.0] * n
    v = [0.0] * n
    tmp = [0.0] * n
    for _ in range(10):
        mult_AtAv(u, v, tmp, n)
        mult_AtAv(v, u, tmp, n)
    vBv = 0.0
    vv = 0.0
    for i in range(n):
        vBv += u[i] * v[i]
        vv += v[i] * v[i]
    print("%.9f" % sqrt(vBv / vv))

if __name__ == "__main__":
    main()
